css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-hz{width:min(1060px,100%);display:grid;gap:1.6em}
.fx-hz .top{display:flex;justify-content:space-between;align-items:end;gap:1em;flex-wrap:wrap}
.fx-hz h2{font-size:clamp(1.8em,4vw,2.6em)}.fx-hz .top p{opacity:.6;font-size:.95em}
.fx-hz .grid{display:grid;grid-template-columns:1.25fr 1fr 1fr;grid-auto-rows:15em;gap:1.1em}
.fx-hz figure{margin:0;position:relative;overflow:hidden;border-radius:var(--radius);isolation:isolate;cursor:pointer;outline:none}
.fx-hz figure:first-child{grid-row:span 2}
.fx-hz .fx-art{position:absolute;inset:0;transition:transform calc(.9s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-hz figcaption{position:absolute;left:0;right:0;bottom:0;padding:2.4em 1.2em 1.1em;color:#fff;display:grid;gap:.15em;background:linear-gradient(transparent,rgba(10,12,18,.62));transform:translateY(60%);opacity:0;transition:transform calc(.5s/var(--speed)) cubic-bezier(.2,.8,.2,1),opacity calc(.4s/var(--speed))}
.fx-hz figcaption b{font:600 1.15em var(--font-heading)}.fx-hz figcaption span{font-size:.82em;opacity:.8}
.fx-hz figure:hover .fx-art,.fx-hz figure:focus-visible .fx-art{transform:scale(1.12)}
.fx-hz figure:hover figcaption,.fx-hz figure:focus-visible figcaption{transform:none;opacity:1}
.fx-hz figure:focus-visible{box-shadow:0 0 0 3px var(--surface),0 0 0 5px var(--accent)}
@media(max-width:700px){.fx-hz .grid{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:11em}.fx-hz figure:first-child{grid-row:auto;grid-column:span 2}
.fx-hz figcaption{transform:none;opacity:1}}
@media(prefers-reduced-motion:reduce){.fx-hz .fx-art,.fx-hz figcaption{transition:none}.fx-hz figure:hover .fx-art,.fx-hz figure:focus-visible .fx-art{transform:none}
.fx-hz figure.is-tap .fx-art{transform:none}}
/* touch: :hover mirrored as .is-tap */
.fx-hz figure.is-tap .fx-art{transform:scale(1.12)}
.fx-hz figure.is-tap figcaption{transform:none;opacity:1}
